import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"PR Routing & Approval","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/pr-routing.md","filePath":"products/ai-coding/cursor/pr-routing.md","lastUpdated":1787042982000}'),i={name:"products/ai-coding/cursor/pr-routing.md"};function s(n,e,l,p,c,d){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="pr-routing-approval" tabindex="-1">PR Routing &amp; Approval <a class="header-anchor" href="#pr-routing-approval" aria-label="Permalink to &quot;PR Routing &amp; Approval&quot;">​</a></h1><p>PR Routing &amp; Approval <strong>routes pull requests to the right reviewers</strong> and can <strong>approve low-risk changes</strong> when your criteria are met. It runs on Automations. It <strong>does not replace a full code review</strong>.</p><blockquote><p>Official: <a href="https://cursor.com/docs/approval-agents" target="_blank" rel="noreferrer">PR Routing &amp; Approval</a>. Configure at <a href="https://cursor.com/automations/from-cursor/pr-routing-and-approval" target="_blank" rel="noreferrer">Automations</a>.</p><p>Policy files: exact basename <strong><code>APPROVAL_POLICY.md</code></strong>, plus optional <code>.cursor/approval-policies/ROUTING.md</code>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Source control connected for the orgs / repos you care about</li><li>Team admin access to <strong>edit</strong> the automation (non-admins can view only)</li><li>Optional: Bugbot and/or <a href="./security-agents.html">Security Agents</a> if you want those findings in the decision</li><li>Security Review Context needs Security Agents on a <strong>team or enterprise</strong> plan</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>After this page you can:</p><ol><li>Turn on reviewer assignment and / or automatic approval separately</li><li>Drop a trusted <code>APPROVAL_POLICY.md</code> in the right directory</li><li>Know which filenames are <strong>ignored</strong></li><li>See why a PR that edits its own policy will not relax review for that same PR</li></ol><hr><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>The agent assigns reviewers from <strong>code ownership and commit history</strong>. It can approve when your <strong>approval criteria</strong>, <strong>risk settings</strong>, <strong>policy files</strong>, <strong>AI reviewer findings</strong>, and <strong>current review state</strong> all line up.</p><p>Two capabilities you enable independently:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Official toggle</th><th>Job</th></tr></thead><tbody><tr><td>Reviewer assignment</td><td><strong>Enable PR Routing and Requests for Review</strong></td><td>Request reviewers</td></tr><tr><td>Risk-based approval</td><td><strong>Automatically Approve PRs</strong></td><td>Approve only after you configure criteria</td></tr></tbody></table><h2 id="signals-it-can-read" tabindex="-1">Signals it can read <a class="header-anchor" href="#signals-it-can-read" aria-label="Permalink to &quot;Signals it can read&quot;">​</a></h2><h3 id="ai-reviewer-awareness" tabindex="-1">AI reviewer awareness <a class="header-anchor" href="#ai-reviewer-awareness" aria-label="Permalink to &quot;AI reviewer awareness&quot;">​</a></h3><ul><li><strong>Bugbot Review Context</strong> — Bugbot findings feed the approval decision</li><li><strong>Security Review Context</strong> — Security Agent findings feed the approval decision</li></ul><p>When enabled, the agent <strong>waits</strong> for those checks to finish. If Bugbot or Security Agents report findings that need human review, PR Routing <strong>will not approve</strong>.</p><p>Security Agents require a <strong>team or enterprise</strong> plan.</p><h3 id="risk-scoring" tabindex="-1">Risk scoring <a class="header-anchor" href="#risk-scoring" aria-label="Permalink to &quot;Risk scoring&quot;">​</a></h3><ul><li><strong>Use Risk Score</strong> — classify the PR (customizable with prompting)</li><li><strong>Maximum Risk Threshold</strong> — highest risk the agent may approve</li></ul><p>If the PR exceeds the threshold, it will not approve.</p><h2 id="policy-files" tabindex="-1">Policy files <a class="header-anchor" href="#policy-files" aria-label="Permalink to &quot;Policy files&quot;">​</a></h2><h3 id="approval-policy-md" tabindex="-1"><code>APPROVAL_POLICY.md</code> <a class="header-anchor" href="#approval-policy-md" aria-label="Permalink to &quot;`APPROVAL_POLICY.md`&quot;">​</a></h3><p>For each changed file, the agent walks that file&#39;s directory and every ancestor looking for this <strong>exact</strong> filename:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APPROVAL_POLICY.md</span></span></code></pre></div><p>Only exact basename matches are trusted. These are <strong>ignored</strong>:</p><ul><li><code>POLICY.md</code></li><li><code>approval_policy.md</code></li><li><code>APPROVAL_POLICY.md.bak</code></li><li><code>team_APPROVAL_POLICY.md</code></li></ul><p>The <strong>closest</strong> applicable file has the highest priority. Ancestor policies still apply unless they conflict with a more specific one.</p><h3 id="cursor-approval-policies-routing-md" tabindex="-1"><code>.cursor/approval-policies/ROUTING.md</code> <a class="header-anchor" href="#cursor-approval-policies-routing-md" aria-label="Permalink to &quot;`.cursor/approval-policies/ROUTING.md`&quot;">​</a></h3><p>Top-level routing file. YAML list of product entries:</p><ul><li><code>product</code> — product or area name</li><li><code>boundary</code> — semantic boundary, or a repository-relative path / glob</li><li><code>policies</code> — policy prompt pointers (paths or semantic descriptions)</li></ul><p>If <code>ROUTING.md</code> is missing, directory-based <code>APPROVAL_POLICY.md</code> discovery <strong>still runs</strong>. Missing routing does not weaken policy discovery.</p><h3 id="precedence" tabindex="-1">Precedence <a class="header-anchor" href="#precedence" aria-label="Permalink to &quot;Precedence&quot;">​</a></h3><p>Applicable approval policy prompts override generic approval criteria, risk thresholds, reviewer-selection guidance, custom approval instructions, and the default automated-review posture.</p><p>If policies conflict: follow the <strong>most specific</strong>. If specificity is unclear: follow the <strong>stricter</strong> instruction and <strong>avoid auto-approval</strong>.</p><p>If a PR <strong>changes</strong> an approval policy, the routing file, a routed policy file, or a reviewer-specific policy file, the agent does <strong>not</strong> use the changed content to relax review for <strong>that same PR</strong>. It uses the <strong>base-branch</strong> version when available, or requires human review.</p><p>Minimal example (shape only — write the actual rules your team needs):</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># APPROVAL_POLICY.md  (docs/ only, for example)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Auto-approve typo and copy edits in this directory.</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Require a human reviewer for any change that touches authentication,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">billing, or dependency versions.</span></span></code></pre></div><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Open <a href="https://cursor.com/automations/from-cursor/pr-routing-and-approval" target="_blank" rel="noreferrer">PR Routing &amp; Approval in Automations</a>.</p><ol><li>Enable routing and / or automatic approval</li><li>Choose organizations and repositories</li><li>Configure <strong>triggers</strong>: <ul><li><strong>PR opened</strong></li><li><strong>PR pushed / updated</strong></li><li><strong>PR commented</strong> (comment matching a regex)</li></ul></li><li>In <strong>Configuration</strong>, pick signals: Bugbot context, Security context, risk score, max risk</li><li>Optional <strong>Custom Prompt</strong> for local expectations. Policy files still win for applicable files. If empty, Cursor-managed defaults apply</li><li>Tools: the agent needs <strong>at least one</strong> primary action — <strong>Request Reviewers</strong> and / or <strong>Approve PR</strong>. Optional: Slack, Microsoft Teams, extra MCP</li><li>Save. Enable or disable later from the detail page</li></ol><p>Triggers can be scoped to repos or orgs. Team admins can set broader team scopes.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>Large monorepo: route by ownership so the right humans see the PR</li><li>Low-risk docs / generated files: auto-approve only where <code>APPROVAL_POLICY.md</code> says so</li><li>Combine with Bugbot + Security Agents so auto-approve <strong>waits</strong> on those findings</li></ul><p>Keep a human review for auth, payments, and anything your policy marks as out of bounds. This product <strong>does not replace</strong> that review.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this</th></tr></thead><tbody><tr><td><code>approval_policy.md</code> or <code>POLICY.md</code></td><td>Exact name <strong><code>APPROVAL_POLICY.md</code></strong></td></tr><tr><td>Expect missing <code>ROUTING.md</code> to disable policies</td><td>Directory discovery still runs</td></tr><tr><td>Edit the policy in the same PR to loosen it</td><td>Agent uses the <strong>base-branch</strong> copy, or requires a human</td></tr><tr><td>Enable auto-approve with no primary action</td><td>Need <strong>Approve PR</strong> (and / or <strong>Request Reviewers</strong>)</td></tr><tr><td>Ignore Bugbot / Security findings</td><td>If those contexts are on and they need a human, <strong>no auto-approve</strong></td></tr><tr><td>Treat it as Bugbot</td><td>Bugbot comments; this <strong>routes and maybe approves</strong></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./security-agents.html">Security Agents</a> — Security Review Context</li><li><a href="./cursor-cookbook.html#review-prs-with-bugbot">Cookbook · Bugbot</a> — Bugbot Review Context</li><li><a href="./cloud-agents.html">Cloud Agents</a> — Automations run Cloud Agents</li><li>Official: <a href="https://cursor.com/docs/approval-agents" target="_blank" rel="noreferrer">PR Routing &amp; Approval</a>, <a href="https://cursor.com/docs/cloud-agent/automations" target="_blank" rel="noreferrer">Automations</a></li></ul>',49)])])}const b=t(i,[["render",s]]);export{f as __pageData,b as default};
